import fs from "node:fs";
import jpeg from "jpeg-js";

export function decodeFrame(filePath) {
  const buf = fs.readFileSync(filePath);
  const decoded = jpeg.decode(buf, { useTArray: true, formatAsRGBA: true });
  return { width: decoded.width, height: decoded.height, rgba: decoded.data };
}

export function rgbaToRgb(rgba, width, height) {
  const rgb = new Uint8Array(width * height * 3);
  for (let i = 0, j = 0; i < rgba.length; i += 4, j += 3) {
    rgb[j] = rgba[i];
    rgb[j + 1] = rgba[i + 1];
    rgb[j + 2] = rgba[i + 2];
  }
  return rgb;
}

export function rgbToRgba(rgb, width, height) {
  const rgba = new Uint8Array(width * height * 4);
  for (let i = 0, j = 0; i < rgb.length; i += 3, j += 4) {
    rgba[j] = rgb[i];
    rgba[j + 1] = rgb[i + 1];
    rgba[j + 2] = rgb[i + 2];
    rgba[j + 3] = 255;
  }
  return rgba;
}

/** Bilinear resize, RGB packed. */
export function resizeRgb(src, sw, sh, dw, dh) {
  const dst = new Uint8Array(dw * dh * 3);
  if (sw <= 0 || sh <= 0 || dw <= 0 || dh <= 0) return dst;
  for (let y = 0; y < dh; y++) {
    const fy = ((y + 0.5) * sh) / dh - 0.5;
    const y0 = Math.max(0, Math.floor(fy));
    const y1 = Math.min(sh - 1, y0 + 1);
    const wy = fy - y0;
    for (let x = 0; x < dw; x++) {
      const fx = ((x + 0.5) * sw) / dw - 0.5;
      const x0 = Math.max(0, Math.floor(fx));
      const x1 = Math.min(sw - 1, x0 + 1);
      const wx = fx - x0;
      const i00 = (y0 * sw + x0) * 3;
      const i01 = (y0 * sw + x1) * 3;
      const i10 = (y1 * sw + x0) * 3;
      const i11 = (y1 * sw + x1) * 3;
      const o = (y * dw + x) * 3;
      for (let c = 0; c < 3; c++) {
        const v =
          src[i00 + c] * (1 - wx) * (1 - wy) +
          src[i01 + c] * wx * (1 - wy) +
          src[i10 + c] * (1 - wx) * wy +
          src[i11 + c] * wx * wy;
        dst[o + c] = v < 0 ? 0 : v > 255 ? 255 : v | 0;
      }
    }
  }
  return dst;
}

export function cropRgb(src, sw, x, y, w, h) {
  const dst = new Uint8Array(w * h * 3);
  for (let row = 0; row < h; row++) {
    const s = ((y + row) * sw + x) * 3;
    dst.set(src.subarray(s, s + w * 3), row * w * 3);
  }
  return dst;
}

export function pasteRgb(dst, dw, src, x, y, w, h) {
  for (let row = 0; row < h; row++) {
    const d = ((y + row) * dw + x) * 3;
    const s = row * w * 3;
    dst.set(src.subarray(s, s + w * 3), d);
  }
}

/** Center 160 crop of a 168 image, plus the mouth mask (black rect). */
export function prep160(rgb168) {
  const real = cropRgb(rgb168, 168, 4, 4, 160, 160);
  const mask = real.slice();
  for (let y = 5; y <= 149; y++) {
    const row = y * 160 * 3;
    mask.fill(0, row + 5 * 3, row + 155 * 3);
  }
  return { real, mask };
}

export function normalizeRgb(rgb) {
  const out = new Float32Array(rgb.length);
  for (let i = 0; i < rgb.length; i++) out[i] = (rgb[i] - 127.5) / 127.5;
  return out;
}

/** HWC RGB float → CHW. */
export function hwcToChw(hwc, h, w, c) {
  const out = new Float32Array(c * h * w);
  for (let ch = 0; ch < c; ch++) {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        out[(ch * h + y) * w + x] = hwc[(y * w + x) * c + ch];
      }
    }
  }
  return out;
}

function gaussianKernel(sigma) {
  const radius = Math.max(1, Math.ceil(sigma * 3));
  const k = new Float32Array(radius * 2 + 1);
  let sum = 0;
  for (let i = -radius; i <= radius; i++) {
    const v = Math.exp(-(i * i) / (2 * sigma * sigma));
    k[i + radius] = v;
    sum += v;
  }
  for (let i = 0; i < k.length; i++) k[i] /= sum;
  return { k, radius };
}

export function unsharpRgb(rgb, w, h) {
  const { k, radius } = gaussianKernel(1.5);
  const tmp = new Float32Array(rgb.length);
  const blur = new Float32Array(rgb.length);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      for (let c = 0; c < 3; c++) {
        let s = 0;
        for (let i = -radius; i <= radius; i++) {
          const xx = Math.min(w - 1, Math.max(0, x + i));
          s += rgb[(y * w + xx) * 3 + c] * k[i + radius];
        }
        tmp[(y * w + x) * 3 + c] = s;
      }
    }
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      for (let c = 0; c < 3; c++) {
        let s = 0;
        for (let i = -radius; i <= radius; i++) {
          const yy = Math.min(h - 1, Math.max(0, y + i));
          s += tmp[(yy * w + x) * 3 + c] * k[i + radius];
        }
        blur[(y * w + x) * 3 + c] = s;
      }
    }
  }
  const out = new Uint8Array(rgb.length);
  for (let i = 0; i < rgb.length; i++) {
    const v = rgb[i] * 1.6 - blur[i] * 0.6;
    out[i] = v < 0 ? 0 : v > 255 ? 255 : Math.floor(v + 0.5);
  }
  return out;
}

/** dest = (mask * dest + (255 - mask) * src) / 255. mask is 160×160. */
export function blendWeight(srcRgb, destRgb, mask) {
  const out = new Uint8Array(destRgb.length);
  for (let i = 0, p = 0; i < mask.length; i++, p += 3) {
    const o = mask[i];
    const inv = 255 - o;
    out[p] = ((o * destRgb[p] + inv * srcRgb[p]) / 255) | 0;
    out[p + 1] = ((o * destRgb[p + 1] + inv * srcRgb[p + 1]) / 255) | 0;
    out[p + 2] = ((o * destRgb[p + 2] + inv * srcRgb[p + 2]) / 255) | 0;
  }
  return out;
}

export function encodeJpeg(rgb, width, height, quality = 90) {
  const rgba = rgbToRgba(rgb, width, height);
  return Buffer.from(jpeg.encode({ data: rgba, width, height }, quality).data);
}

export function parseWav(buf) {
  if (buf.toString("ascii", 0, 4) !== "RIFF" || buf.toString("ascii", 8, 12) !== "WAVE") {
    throw new Error("not a WAV file");
  }
  let offset = 12;
  let channels = 1;
  let rate = 16000;
  let bits = 16;
  let data = null;
  while (offset + 8 <= buf.length) {
    const id = buf.toString("ascii", offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    const body = offset + 8;
    if (id === "fmt ") {
      channels = buf.readUInt16LE(body + 2);
      rate = buf.readUInt32LE(body + 4);
      bits = buf.readUInt16LE(body + 14);
    } else if (id === "data") {
      data = buf.subarray(body, body + size);
      break;
    }
    offset = body + size + (size & 1);
  }
  if (!data) throw new Error("WAV data chunk missing");
  return { channels, rate, bits, data };
}

/** Downmix + linear resample to 16 kHz mono s16le. */
export function toPcm16k(wav) {
  const { channels, rate, bits, data } = parseWav(wav);
  if (bits !== 16) throw new Error(`WAV bits ${bits} not supported, need 16`);
  const samples = (data.length / 2 / channels) | 0;
  const mono = new Float32Array(samples);
  for (let i = 0; i < samples; i++) {
    let s = 0;
    for (let c = 0; c < channels; c++) s += data.readInt16LE((i * channels + c) * 2);
    mono[i] = s / channels;
  }
  const outCount = Math.max(1, Math.round((samples * 16000) / rate));
  const pcm = Buffer.alloc(outCount * 2);
  for (let i = 0; i < outCount; i++) {
    const src = (i * rate) / 16000;
    const i0 = Math.min(samples - 1, src | 0);
    const i1 = Math.min(samples - 1, i0 + 1);
    const f = src - i0;
    const v = mono[i0] * (1 - f) + mono[i1] * f;
    let q = Math.round(v);
    if (q > 32767) q = 32767;
    if (q < -32768) q = -32768;
    pcm.writeInt16LE(q, i * 2);
  }
  return pcm;
}
